script:
frappe.ui.form.on("Shipment", {

    refresh(frm) {

        frm.add_custom_button(__('Import From'), function () {

            const dialog = new frappe.ui.Dialog({
                title: __('Select Source'),
                fields: [
                    {
                        fieldname: 'source',
                        fieldtype: 'Select',
                        label: 'Fetch From',
                        options: [
                            'Delivery Note',
                            'Purchase Order'
                        ],
                        reqd: 1
                    }
                ],

                primary_action_label: __('Next'),

                primary_action(values) {

                    dialog.hide();

                    if (values.source === "Delivery Note") {
                        fetch_from_delivery_note(frm);
                    }

                    if (values.source === "Purchase Order") {
                        fetch_from_purchase_order(frm);
                    }
                }
            });

            dialog.show();

        });

    },

    // ===============================
    // FINAL VALIDATION BEFORE SAVE
    // ===============================

    validate(frm) {

        (frm.doc.custom_shipment_box || []).forEach(row => {

            if (row.net_weight > row.gross_weight) {

                frappe.throw(
                    `Row ${row.idx}: Net Weight cannot be greater than Gross Weight`
                );

            }

        });

    }
});




// ==========================================================
// FETCH FROM DELIVERY NOTE
// ==========================================================

function fetch_from_delivery_note(frm) {

    if (!frm.doc.delivery_customer) {
        frappe.msgprint(__('Please select Delivery Customer first'));
        return;
    }

    frappe.prompt([
        {
            fieldname: 'delivery_note',
            fieldtype: 'Link',
            options: 'Delivery Note',
            label: 'Delivery Note',
            reqd: 1,

            get_query: function () {
                return {
                    filters: {
                        customer: frm.doc.delivery_customer,
                        docstatus: 1
                    }
                };
            }
        }
    ],

    function(values) {

        frappe.call({
            method: "get_shipment_items",
            args: {
                source: "Delivery Note",
                reference: values.delivery_note
            },

            callback: function(r) {

                if (!r.message || !r.message.length) {
                    frappe.msgprint(__('No items found'));
                    return;
                }

                open_items_dialog(frm, r.message, "Delivery Note", values.delivery_note);
            }
        });

    },

    __('Select Delivery Note'),
    __('Fetch'));
}


// ==========================================================
// FETCH FROM PURCHASE ORDER
// ==========================================================

function fetch_from_purchase_order(frm) {

    // Supplier mandatory
    if (!frm.doc.pickup_supplier) {
        frappe.msgprint(__('Please select Supplier first'));
        return;
    }

    frappe.prompt([
        {
            fieldname: 'purchase_order',
            fieldtype: 'Link',
            options: 'Purchase Order',
            label: 'Purchase Order',
            reqd: 1,

            get_query: function () {
                return {
                    filters: {
                        supplier: frm.doc.pickup_supplier,
                        docstatus: 1
                    }
                };
            }
        }
    ],

    function(values) {

        frappe.call({
            method: "get_shipment_items",
            args: {
                source: "Purchase Order",
                reference: values.purchase_order
            },

            callback: function(r) {

                if (!r.message || !r.message.length) {
                    frappe.msgprint(__('No items found in this Purchase Order'));
                    return;
                }

                open_items_dialog(frm, r.message, "Purchase Order", values.purchase_order);
            }
        });

    },

    __('Select Purchase Order'),
    __('Fetch'));
}


// ==========================================================
// COMMON ITEM SELECTION DIALOG
// ==========================================================

function open_items_dialog(frm, items, source, reference) {

    const dialog = new frappe.ui.Dialog({
        title: __('Select Items'),
        size: 'extra-large',

        fields: [
            {
                fieldname: 'items',
                fieldtype: 'Table',
                cannot_add_rows: true,

                data: items.map(d => ({
                    select: 1,
                    item_code: d.item_code,
                    item_name: d.item_name,
                    description: d.description,
                    qty: d.qty,
                    uom: d.uom
                })),

                fields: [
                    {
                        fieldtype:'Check',
                        fieldname:'select',
                        label:'Select',
                        in_list_view:1
                    },
                    {
                        fieldtype:'Data',
                        fieldname:'item_code',
                        label:'Item Code',
                        read_only:1,
                        in_list_view:1
                    },
                    {
                        fieldtype:'Data',
                        fieldname:'item_name',
                        label:'Item Name',
                        read_only:1,
                        in_list_view:1
                    },
                    // {
                    //     fieldtype:'Data',
                    //     fieldname:'description',
                    //     label:'Description',
                    //     read_only:1,
                    //     in_list_view:1
                    // },
                    {
                        fieldtype:'Float',
                        fieldname:'qty',
                        label:'Qty',
                        in_list_view:1
                    },
                    {
                        fieldtype:'Data',
                        fieldname:'uom',
                        label:'UOM',
                        read_only:1,
                        in_list_view:1
                    }
                ]
            }
        ],

        primary_action_label: __('Add to Shipment'),

        primary_action(values) {

            const selected = (values.items || []).filter(
                row => row.select && row.qty > 0
            );

            if (!selected.length) {
                frappe.msgprint(__('Please select at least one item'));
                return;
            }

         selected.forEach(row => {

    let child = frm.add_child("custom_shipment_box");

    // PREFIX BASED ON SOURCE
    let prefix = source === "Purchase Order" ? "P" : "D";

    // COUNT EXISTING BOXES OF SAME TYPE
    let count = frm.doc.custom_shipment_box.filter(d => {
        if (source === "Purchase Order") {
            return d.purchase_order;
        }
        if (source === "Delivery Note") {
            return d.delivery_note;
        }
    }).length + 1;

    // ASSIGN INNER BOX NUMBER
    child.inner_box_no = prefix + count;

    if (source === "Delivery Note") {
        child.delivery_note = reference;
    }

    if (source === "Purchase Order") {
        child.purchase_order = reference;
    }

    child.item_code = row.item_code;
    child.item_description = row.description;
    child.qty = row.qty;
    child.uom = row.uom;

    child.packed = 0;
    child.net_weight = 0;
    child.gross_weight = 0;

});

            frm.refresh_field("custom_shipment_box");

            dialog.hide();
        }
    });

    dialog.show();
}
